int mettre_a_jour(Cache *c, int cle)
{
    pthread_mutex_lock(&c->verrou);
    if (!valide(cle))
        return -1;
    c->donnees[cle]++;
    pthread_mutex_unlock(&c->verrou);
    return 0;
}
